entries.badExample:
function invoice(order) {
  // 逐项计算数量折扣和会员折扣
  let subtotal = 0;
  for (const item of order.items) {
    const rate = item.quantity >= 10 ? 0.9 : 1;
    subtotal += item.price * item.quantity * rate;
  }
  if (order.member) subtotal *= 0.95;
  // 按地区税率和免税额计算税额
  const taxRate = order.region === "north" ? 0.06 : 0.08;
  const taxable = Math.max(0, subtotal - order.taxAllowance);
  const tax = Math.round(taxable * taxRate);
  // 生成发票文本、打印并保存
  const total = subtotal + tax;
  const text = [`订单 ${order.id}`, `小计 ${subtotal}`, `税额 ${tax}`, `合计 ${total}`].join("\n");
  printer.print(text);
  saveInvoice({ orderId: order.id, subtotal, tax, total, text });
}

entries.goodExample:
function invoice(order) {
  const subtotal = discountedSubtotal(order.items, order.member);
  const tax = taxFor(subtotal, order.region, order.taxAllowance);
  const totals = { subtotal, tax, total: subtotal + tax };
  const text = invoiceText(order.id, totals);
  printer.print(text);
  saveInvoice({ orderId: order.id, ...totals, text });
}
// 三段计算分别提取为 discountedSubtotal、taxFor 和 invoiceText

